import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';

type WalletSortPriority = 'default' | 'primary';

type SortWalletsForDisplayOptions = {
  priority?: WalletSortPriority;
};

const getWalletDisplayOrder = (wallet: UserWalletResponse, priority: WalletSortPriority) => {
  const aliasNm = wallet.aliasNm?.trim() ?? '';
  const isPriorityWallet =
    priority === 'primary' ? wallet.priAliasNm === wallet.aliasNm : wallet.dfltAliasNm === wallet.aliasNm;
  const isWalletBlocked = Boolean(wallet.isWalletBlocked);

  if (isWalletBlocked) {
    return 3;
  }

  if (isPriorityWallet) {
    return 0;
  }

  if (!aliasNm) {
    return 2;
  }

  return 1;
};

export const sortWalletsForDisplay = (wallets: UserWalletResponse[], options: SortWalletsForDisplayOptions = {}) => {
  const { priority = 'default' } = options;

  return [...wallets].sort((leftWallet, rightWallet) => {
    const leftOrder = getWalletDisplayOrder(leftWallet, priority);
    const rightOrder = getWalletDisplayOrder(rightWallet, priority);

    return leftOrder - rightOrder;
  });
};
